/* Opponent pages render the supplied profiles, including every sample size. */
let opponentProfiles=null,villainData=null,opponentName='Ben';
const statLabels={vpip:'VPIP',pfr:'PFR',rfi:'RFI',rfi_btn:'RFI · BTN',rfi_sb:'RFI · SB',open_limp_when_first_in:'Limp when first in',iso_raise_vs_limp:'Iso-raise vs limp',bb_fold_vs_open:'BB fold vs open',bb_3bet_vs_open:'BB 3-bet vs open',three_bet:'3-bet',fold_to_3bet:'Fold to 3-bet',four_bet_vs_3bet:'4-bet vs 3-bet',cbet_flop:'Flop c-bet',fold_to_cbet:'Fold to c-bet',raise_vs_cbet:'Raise vs c-bet',barrel_turn:'Turn barrel',barrel_river:'River barrel',fold_to_bet_flop:'Fold to flop bet',fold_to_bet_turn:'Fold to turn bet',fold_to_bet_river:'Fold to river bet',check_raise:'Check-raise',wtsd:'WTSD',wsd:'W$SD',showdown_weak_hands:'Pair or worse at showdown',river_aggression_weak_at_showdown:'Weak hands in shown-down river bets',aggression_factor:'Aggression factor',all_in_hands:'All-in hands'};
const statGroups={Preflop:['vpip','pfr','rfi','rfi_btn','rfi_sb','open_limp_when_first_in','iso_raise_vs_limp','bb_fold_vs_open','bb_3bet_vs_open'],'3-bet war':['three_bet','fold_to_3bet','four_bet_vs_3bet'],Flop:['cbet_flop','fold_to_cbet','raise_vs_cbet'],'Later streets':['barrel_turn','barrel_river','fold_to_bet_flop','fold_to_bet_turn','fold_to_bet_river','check_raise'],Showdown:['wtsd','wsd','showdown_weak_hands','river_aggression_weak_at_showdown'],'Other':['aggression_factor','all_in_hands']};
function badge(n){const st=SpotEngine.status(n);return `<span class="sample-badge ${st}">${st}</span>`}
function caveats(){return `<aside class="notice">${opponentProfiles.caveats.map(esc).join(' ')}</aside>`}
function statDefinition(key){return opponentProfiles.stat_definitions[key]||(key==='rfi_btn'?'Raise first in from the button.':key==='rfi_sb'?'Raise first in from the small blind.':key==='aggression_factor'?'Bets and raises divided by calls; this is a ratio, not a percentage.':'Definition not supplied.')}
function tableAverage(key){const rows=Object.values(opponentProfiles.players).map(p=>p.stats[key]).filter(s=>s?.pct!==undefined&&Number.isFinite(s.num)&&s.n>0),n=rows.reduce((n,s)=>n+s.n,0);return n?rows.reduce((a,s)=>a+s.num,0)/n*100:null}
function playerLink(name,ref,label){return `<button class="text-link" data-opponent="${esc(name)}" data-stat-ref="${esc(ref)}">${esc(label)}</button>`}
function sizingValue(value,n,suffix='bb'){return n&&value!==null?value+suffix:'—'}
function latestSessionHTML(p){const x=p.latest_session;if(!x)return '';const pctStat=k=>x.stats[k].n?x.stats[k].pct.toFixed(1)+'%':'—';return `<section class="panel latest-session"><div class="eyebrow">Latest game · Nov 5, 2026</div><h3>${x.hands} new hands</h3><p class="source">${x.avg_table_size}-handed average · ${esc(x.source_file)}${x.log_name?` · logged as ${esc(x.log_name)}`:''}. Rates below describe this session only; the main observed-stat table combines count-based opportunities.</p><div class="metrics">${[['vpip','VPIP'],['pfr','PFR'],['three_bet','3-bet']].map(([k,label])=>`<div class="metric"><strong>${pctStat(k)}</strong><span>${label} · ${x.stats[k].num} / ${x.stats[k].n}</span></div>`).join('')}</div><details><summary>All latest-session stats and sizing</summary><div class="stat-table-wrap"><table class="opponent-stats"><thead><tr><th>Stat</th><th>Latest session</th><th>Count / opportunities</th></tr></thead><tbody>${Object.entries(x.stats).map(([k,v])=>`<tr><th>${esc(statLabels[k]||k)}</th><td>${v.pct!==undefined?v.n?v.pct.toFixed(1)+'% of observed opportunities':'—':v.value===null?'—':v.value+' ratio'}</td><td>${v.num??'—'} / ${v.n}</td></tr>`).join('')}</tbody></table></div><div class="stats-row"><span>Median open</span><span>${sizingValue(x.sizing.open_raise_bb_median.value,x.sizing.open_raise_bb_median.n)} · n=${x.sizing.open_raise_bb_median.n}</span></div><div class="stats-row"><span>Median 3-bet</span><span>${sizingValue(x.sizing.three_bet_bb_median.value,x.sizing.three_bet_bb_median.n)} · n=${x.sizing.three_bet_bb_median.n}</span></div>${Object.entries(x.sizing.bet_pct_pot_median).map(([street,v])=>`<div class="stats-row"><span>Median ${street} bet</span><span>${sizingValue(v,x.sizing.bets_counted[street],'% pot')} · n=${x.sizing.bets_counted[street]}</span></div>`).join('')}<p class="source">Latest-session aggression: ${x.stats.aggression_factor.aggressive} bets/raises / ${x.stats.aggression_factor.calls} calls. Sizing medians use the actual new-session samples.</p></details></section>`}
function showOpponents(){
 if(!opponentProfiles){shell('<div class="page"><h1>Opponent data unavailable.</h1></div>','Opponents');return}
 const p=opponentProfiles.players[opponentName],notes=p.study_notes;
 const noteHTML=n=>`<div class="study-rule">${badge(n.n)} <span class="source">n=${n.n}</span><p>${esc(n.rule)}</p>${playerLink(opponentName,n.stat_ref,'View driving stat')}</div>`;
 shell(`<div class="page opponents"><div class="eyebrow">Your home-game notebook</div><h1>${opponentName==='Tiger'?'My leaks':esc(opponentName)}</h1><p class="muted">Personal notes, not solver output.</p><div class="choices">${Object.keys(opponentProfiles.players).map(n=>`<button data-opponent="${esc(n)}" class="${n===opponentName?'selected':''}">${n==='Tiger'?'My leaks':n}</button>`).join('')}</div>${caveats()}${p.identity_note?`<p class="notice">${esc(p.identity_note)}</p>`:''}${latestSessionHTML(p)}<section class="panel notebook"><h3>Study notes</h3>${notes.filter(n=>n.n>=30).map(noteHTML).join('')}${notes.some(n=>n.n<30)?`<details><summary>Hidden observations · sample under 30</summary>${notes.filter(n=>n.n<30).map(noteHTML).join('')}</details>`:''}</section><section class="panel"><div class="stats-row"><h3>Observed stats</h3><span class="source">${p.hands.toLocaleString()} hands · ${p.historical_avg_table_size?`${p.historical_avg_table_size}-handed historical average · ${p.latest_session.avg_table_size}-handed latest session`:`${p.avg_table_size}-handed average`}</span></div><p class="source">Percentages describe observed opportunities in the supplied logs, not per-hand strategy frequencies. Table comparison pools counts across all supplied player profiles, weighted by opportunities.</p>${Object.entries(statGroups).map(([group,keys])=>`<h4>${group}</h4><div class="stat-table-wrap"><table class="opponent-stats"><thead><tr><th>Stat / definition</th><th>Observed rate</th><th>Count / opportunities</th><th>Table average</th><th>Bluff benchmark</th></tr></thead><tbody>${keys.filter(k=>p.stats[k]).map(k=>{let s=p.stats[k],avg=tableAverage(k);return `<tr id="stat-${k}" class="${s.n<30?'small-sample':''}"><th><button data-stat-definition="${k}">${esc(statLabels[k]||k)}</button></th><td>${s.pct!==undefined?s.n?s.pct.toFixed(1)+'% of observed opportunities':'—':s.value===null?'—':s.value+' ratio'}${s.scope_note?`<p class="source">${esc(s.scope_note)}</p>`:''} ${badge(s.n)}</td><td>${s.num??'—'} / ${s.n}</td><td>${avg===null?'—':avg.toFixed(1)+'% of observed opportunities'}</td><td>${s.benchmark_pct!==undefined?(s.benchmark_approximate?'~':'')+s.benchmark_pct.toFixed(1)+'% break-even folds':'—'}</td></tr>`}).join('')}</tbody></table></div>`).join('')}</section><section class="panel"><h3>Observed sizing${p.sizing.scope_note?' · historical samples':''}</h3>${p.sizing.scope_note?`<p class="source">${esc(p.sizing.scope_note)}</p>`:''}<div class="stats-row" id="stat-open_raise_bb_median"><span>Median open</span><span>${sizingValue(p.sizing.open_raise_bb_median.value,p.sizing.open_raise_bb_median.n)} · n=${p.sizing.open_raise_bb_median.n}</span></div><div class="stats-row" id="stat-three_bet_bb_median"><span>Median 3-bet</span><span>${sizingValue(p.sizing.three_bet_bb_median.value,p.sizing.three_bet_bb_median.n)} · n=${p.sizing.three_bet_bb_median.n}</span></div>${Object.entries(p.sizing.bet_pct_pot_median).map(([street,v])=>`<div class="stats-row"><span>Median ${street} bet</span><span>${sizingValue(v,p.sizing.bets_counted[street],'% pot')} · n=${p.sizing.bets_counted[street]}</span></div>`).join('')}</section>${opponentName==='Tiger'?'':`<button class="primary" data-drill-player="${esc(opponentName)}" ${villainData.spots.some(s=>s.villain===opponentName)?'':'disabled'}>${villainData.spots.some(s=>s.villain===opponentName)?'Drill this player':'Profile only · no drills yet'} ${svgIcon('next')}</button>`}<p class="source">${esc(opponentProfiles.meta.source)}</p></div>`,'Opponents');
}
function openOpponent(name,ref){opponentName=name;session=null;screen='opponents';showOpponents();if(ref){const key=ref.split('.').at(-1),el=document.getElementById('stat-'+key);el?.scrollIntoView({block:'center'});el?.classList.add('stat-focus')}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.opponent)openOpponent(b.dataset.opponent,b.dataset.statRef);if(b.dataset.statDefinition)modal(`<h3>${esc(statLabels[b.dataset.statDefinition]||b.dataset.statDefinition)}</h3><p>${esc(statDefinition(b.dataset.statDefinition))}</p>`)});
